<div class=""> <div style="float:left" class="text-left upload_{{ $rand }}"></div><div style="float:left;clear: both;margin-top: 10px;" class=" upload_{{ $rand }}_preview">@if ($filename !== '')<a style='float:left;' target='_blank' href='{{ legacy_href() }}download_file?path={{ urlencode($blob.$filename) }}&filename={{ $filename }}'>{{ $filename }}</a>@endif</div><input type="hidden" class="" id="upload_{{ $rand }}" name="upload_{{ $rand }}" value="{{ $filename }}" /></div><script>$(".upload_{{ $rand }}").dropper({action: rooturl + 'system_upload_2',label: "{!! res('click_to_add_attachment') !!}",maxQueue : 1,}).on("start.dropper", {{ $rand }}_start).on("fileComplete.dropper", {{ $rand }});function {{ $rand }}(e, file, response) { if (response.trim() === "" || response.toLowerCase().indexOf("error") > -1) { ErrorBox("{!! res('error_upload') !!}", true);  } else { var x = response.split("[NIDA]");  $(".upload_{{ $rand }}_preview").html("<a download=" + x[1] + " href='{{ $blob }}/" + x[0] +"'>" + x[1] +"</a>");  $("input[name='upload_{{ $rand }}']").val(x[0]); $(".upload_{{ $rand }}_delete").css("display", "block"); on_uploadcomplate('{{ $rand }}', ''+ response +'');  }}function {{ $rand }}_start(e, file, response) { $(".upload_{{ $rand }}_preview").html("<img src='{{ legacy_href() }}assets/images/loading.gif' />");  $(".upload_{{ $rand }}_delete").css("display", "none");}</script>
